#!/usr/bin/env python3
"""Fixed host fixture operations. No workspace program receives App credentials."""
import fcntl, hashlib, json, os, shutil, subprocess, sys, time
from pathlib import Path
ROOT=Path(__file__).resolve().parent
HOST=Path('/home/gem/.local/share/codexsymphony/gate-host/releases/53d3d21a669910a8')
sys.path.insert(0,str(HOST))
from isolation import command
AUDIT=ROOT/'audit'
OUT=Path('/home/gem/.local/share/codexsymphony/workspaces/GH-121/artifacts/gh121/real-delivery-core-8f5ed89')
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def save(path,value):
    temp=path.with_suffix('.tmp')
    with temp.open('w') as f:
        json.dump(value,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
    temp.replace(path)
def export():
    for p in (ROOT/'validation').rglob('*'):
        if p.is_file() and not p.is_symlink():
            name='validation--'+'--'.join(p.relative_to(ROOT/'validation').parts)
            if p.stat().st_size>8*1024*1024: raise ValueError('validation evidence exceeds bound')
            (AUDIT/(name+'.json' if p.suffix=='.json' else name+'.stdout')).write_bytes(p.read_bytes())
    directory=os.open('/',os.O_DIRECTORY)
    try:
        for part in OUT.parts[1:]:
            child=os.open(part,os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=directory)
            os.close(directory);directory=child
        files={}
        def write(name,data):
            fd=os.open(name,os.O_WRONLY|os.O_CREAT|os.O_TRUNC|os.O_NOFOLLOW,0o600,dir_fd=directory)
            with os.fdopen(fd,'wb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
        for p in sorted(AUDIT.iterdir()):
            if p.suffix not in ('.json','.stdout','.stderr'): continue
            # Rust errors contain only fixed codes; validation has no credentials.
            if p.stat().st_size>8*1024*1024: raise ValueError('diagnostic exceeds bound; preserve host file')
            data=p.read_bytes();write(p.name,data)
            files[p.name]={'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)}
        write('files.json',json.dumps({'files':files,'complete':True},indent=2).encode())
    finally:os.close(directory)
def verify():
    frozen=json.loads((ROOT/'frozen.json').read_text())
    for name,sha in frozen['host_dependencies'].items():
        if digest(Path(name))!=sha: raise ValueError('host isolation dependency changed')
    for name,sha in frozen['files'].items():
        p=ROOT/name
        if p.is_symlink() or digest(p)!=sha: raise ValueError('host fixture digest mismatch: '+name)
    return frozen
def isolated(mode):
    readonly=[ROOT/'adapter-runner',ROOT/'policy.json',ROOT/'protection.json',ROOT/'rules.json']
    writable=[AUDIT,ROOT/'data']
    if mode!='prepare': readonly.append(ROOT/'database-url')
    if mode=='validate':
        readonly.append(ROOT/'validation-entry')
        writable += [ROOT/'validation',ROOT/'nested-run']
    if mode=='prepare': readonly.append(ROOT/'seed.bundle')
    elif mode!='validate': readonly += [ROOT/'github.json',Path('/home/gem/.secrets/symphony-delivery.private-key.pem')]
    env={'RUST_LOG':'error','GIT_TERMINAL_PROMPT':'0'}
    # Only reviewed proxy routing, never product DB/runtime/auth environment.
    hostenv=Path('/home/gem/.local/share/codexsymphony/a01-gh24/releases/storage-scope-7c592b0/product.env')
    for line in hostenv.read_text().splitlines():
        if '=' in line:
            k,v=line.split('=',1)
            if k.lower() in ('http_proxy','https_proxy','all_proxy','no_proxy'): env[k]=v
    if mode not in ('prepare','validate'):
        for suffix,name in [('branches/main/protection','protection.json'),('rules/branches/main','rules.json')]:
            # Independent read-only operator audit; product App retains its own narrow token policy.
            p=subprocess.run(['/usr/bin/gh','api','repos/musutrade/disposable-2/'+suffix],capture_output=True,timeout=45,env={**os.environ,**env})
            if p.returncode or json.loads(p.stdout)!=json.loads((ROOT/name).read_text()):
                raise ValueError('frozen GitHub protection unavailable or changed')
        save(AUDIT/'protection-audit.json',{'matched':True,'at':int(time.time()),'repository_id':1377749969,
             'protection_sha256':digest(ROOT/'protection.json'),'rules_sha256':digest(ROOT/'rules.json')})
    args=command([ROOT/'adapter-runner',mode],run=ROOT/'run',repository=ROOT/'driver',plugins=HOST,
                 readonly=readonly,writable=writable,environment=env,cwd=ROOT/'driver')
    return run(args,mode,180)
def run(args,label,timeout):
    with (AUDIT/(label+'.stdout')).open('wb') as out,(AUDIT/(label+'.stderr')).open('wb') as err:
        p=subprocess.Popen(args,stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True)
        try: code=p.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            import signal
            os.killpg(p.pid,signal.SIGKILL);p.wait();code=124
    save(AUDIT/(label+'-execution.json'),{'exit_code':code,'at':int(time.time()),'timeout_seconds':timeout})
    if code: raise RuntimeError(label+' failed; complete diagnostics exported')
def validate():
    isolated("validate")
def main():
    os.umask(0o077)
    mode=sys.argv[1] if len(sys.argv)==2 else ''
    if mode not in ('setup','submit','observe'): raise ValueError('operation must be setup/submit/observe')
    with (ROOT/'lock').open('a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        frozen=verify()
        try:
            if mode=='setup':
                if not (AUDIT/'manifest.json').exists(): isolated('prepare')
                validate();isolated('preflight')
                save(AUDIT/'setup.json',{'status':'READY','repository_id':1377749969,
                    'scenario':'validation_service -> durable outbox -> github_publication_adapter -> delivery_extension -> real push/create/observe; one fixed branch/PR; no merge',
                    'frozen':frozen,'candidate_implementation_accepted':False,'product_commit':'8f5ed89af8d098bf34f9d816fdcf50d9252f2ef4'})
            else:
                if json.loads((AUDIT/'setup.json').read_text())['status']!='READY': raise ValueError('setup missing')
                isolated(mode)
        finally: export()
    print(json.dumps({'operation':mode,'status':'completed','evidence':str(OUT)}))
if __name__=='__main__':main()

