#!/usr/bin/env python3
"""Credential-isolated GH-121 fixture RPC. Fixed operations, no agent code/argv."""
import hashlib,json,os,re,stat,subprocess,time
from pathlib import Path
ROOT=Path(__file__).resolve().parent
SPOOL=Path('/home/gem/.local/share/codexsymphony/workspaces/GH-121/.agent-env/core-8f5ed89')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def atomic(p,v):
    tmp=p.with_suffix('.tmp')
    with tmp.open('w') as f:json.dump(v,f);f.flush();os.fsync(f.fileno())
    tmp.replace(p)
def perform(value):
    if not isinstance(value,dict) or set(value)!={'operation','fixture_sha256'}:raise ValueError('invalid request fields')
    if value['operation'] not in ('setup','submit','observe'):raise ValueError('unsupported operation')
    approved=json.loads((ROOT/'broker-approval.json').read_text())
    if value['fixture_sha256']!=approved['fixture_sha256'] or sha(ROOT/'frozen.json')!=approved['fixture_sha256']:raise ValueError('fixture identity mismatch')
    if sha(ROOT/'runner.py')!=approved['runner_sha256']:raise ValueError('runner changed')
    p=subprocess.run([str(ROOT/'runner.py'),value['operation']],stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=540,start_new_session=True,
        env={'PATH':'/usr/local/bin:/usr/bin:/bin','HOME':'/home/gem','XDG_RUNTIME_DIR':f'/run/user/{os.getuid()}'})
    return {'ok':p.returncode==0,'exit_code':p.returncode,'fixture_sha256':approved['fixture_sha256'],
        'evidence':'artifacts/gh121/real-delivery-core-8f5ed89/files.json','gh121_implementation_accepted':False}
def main():
    os.umask(0o077)
    spool=os.open(SPOOL,os.O_DIRECTORY|os.O_NOFOLLOW)
    journal=ROOT/'requests';journal.mkdir(exist_ok=True)
    while True:
        for name in os.listdir(spool):
            if not re.fullmatch(r'[0-9a-f]{32}\.request\.json',name):continue
            result_name=name.replace('.request.','.result.')
            if result_name in os.listdir(spool):continue
            receipt=journal/name
            try:
                if receipt.exists():
                    record=json.loads(receipt.read_text())
                    result=record.get('result',{'ok':False,'error':'prior operation unknown; host reconciliation required'})
                else:
                    fd=os.open(name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=spool)
                    with os.fdopen(fd,'rb') as f:
                        if not stat.S_ISREG(os.fstat(f.fileno()).st_mode):raise ValueError('regular file required')
                        raw=f.read(2049)
                    if len(raw)>2048:raise ValueError('request too large')
                    value=json.loads(raw)
                    record={'status':'started','request_sha256':hashlib.sha256(raw).hexdigest(),'at':int(time.time())}
                    atomic(receipt,record)
                    result=perform(value)
                    record.update(status='finished',result=result);atomic(receipt,record)
            except Exception as e:
                result={'ok':False,'error_type':type(e).__name__,'error':str(e)[:256]}
                if receipt.exists():
                    record=json.loads(receipt.read_text());record.update(status='failed',result=result);atomic(receipt,record)
            try:
                fd=os.open(result_name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600,dir_fd=spool)
